import json

def transform(grid):
    sources = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0:
                sources.append((r, c, grid[r][c]))

    if not sources:
        return grid

    result = [row[:] for row in grid]

    # Clear non-source cells initially
    for r in range(len(result)):
        for c in range(len(result[0])):
            if grid[r][c] != 0:
                pass
            else:
                result[r][c] = 0

    # First, clear everything except sources
    for r in range(len(result)):
        for c in range(len(result[0])):
            if grid[r][c] == 0:
                result[r][c] = 0

    # Add source projections
    for src in sources:
        r, c, val = src

        if val == 1:
            new_r, new_c = r - 1, c + 2
            if 0 <= new_r < len(result) and 0 <= new_c < len(result[0]):
                result[new_r][new_c] = 1
        elif val == 2:
            new_c = c - 4
            if 0 <= new_c < len(result[0]):
                result[r][new_c] = 2
        elif val == 3:
            # (0, +1) and (+3, 0)
            new_c = c + 1
            if 0 <= new_c < len(result[0]):
                result[r][new_c] = 3
            new_r = r + 3
            if 0 <= new_r < len(result):
                result[new_r][c] = 3
        elif val == 6:
            new_r = r - 6
            if 0 <= new_r < len(result):
                result[new_r][c] = 6

    # Now fill 5s at all unique non-source positions
    # The key insight: 5s fill "between" positions for sources with the SAME row or same col
    # But also fill at intersections (r1, c2) and (r2, c1)

    # Actually, looking at Demo 1 more carefully:
    # Sources: (4,3) and (7,5)
    # 5s appear at: (4,4),(4,5),(7,2),(7,3),(7,4)
    # That's: row 4 cols 4-5 (between 3 and 5 extended), row 7 cols 2-4 (extended past?)

    # Let me try filling all positions between source projections
    positions_to_fill = set()
    for src in sources:
        r, c, val = src
        if val == 1:
            positions_to_fill.add((r-1, c+2))
        elif val == 2:
            positions_to_fill.add((r, c-4))
        elif val == 3:
            positions_to_fill.add((r, c+1))
            positions_to_fill.add((r+3, c))
        elif val == 6:
            positions_to_fill.add((r-6, c))

    # Also add all cells that are "on the path" between any two sources
    for i, src1 in enumerate(sources):
        for j, src2 in enumerate(sources):
            if i >= j:
                continue
            r1, c1, v1 = src1
            r2, c2, v2 = src2

            # Check if they share a row
            if r1 == r2:
                min_c, max_c = min(c1, c2), max(c1, c2)
                for c in range(min_c, max_c):
                    positions_to_fill.add((r1, c))

            # Check if they share a col
            if c1 == c2:
                min_r, max_r = min(r1, r2), max(r1, r2)
                for r in range(min_r, max_r):
                    positions_to_fill.add((r, c2))

    # Fill 5s at all these positions
    for pos in positions_to_fill:
        r, c = pos
        if 0 <= r < len(result) and 0 <= c < len(result[0]):
            if result[r][c] == 0:
                result[r][c] = 5

    # Finally, re-apply source projections on top (they don't get overwritten)
    for src in sources:
        r, c, val = src
        if result[r][c] != 0:
            result[r][c] = val  # Ensure source value at source position

    return result

