import json

def transform_v1(grid):
    """
    Rule:
    1. Each source projects to a new position based on its value
    2. Cells on the straight-line path between source and projection become 5s (excluding endpoints)
    3. Projections keep original values
    """
    sources = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0:
                sources.append((r, c, grid[r][c]))

    if not sources:
        return grid

    result = [row[:] for row in grid]

    # Clear all
    for r in range(len(result)):
        for c in range(len(result[0])):
            result[r][c] = 0

    # Add sources back
    for src in sources:
        r, c, val = src
        result[r][c] = val

    # Add projections
    for src in sources:
        r, c, val = src
        if val == 1:
            pr, pc = r - 1, c + 2  # diag (-1, +2)
        elif val == 2:
            pr, pc = r, c - 4  # horiz (-4)
        elif val == 3:
            # Two projections for value 3?
            pass  # Need to figure this
        elif val == 6:
            pr, pc = r - 6, c  # vert (-6)
        else:
            pr, pc = r, c  # No projection or keep in place

        if pr != r or pc != c:
            # Draw line from (r,c) to (pr,pc)
            dr = pr - r
            dc = pc - c
            if dr == 0 and dc == 0:
                continue
            # Simple: if dx and dy have same sign, go through intermediate cells
            if dr * dc > 0:  # Same direction quadrant
                steps = max(abs(dr), abs(dc))
                for i in range(1, steps):
                    nr, nc = r + int(dr * i / steps), c + int(dc * i / steps)
                    if 0 <= nr < len(result) and 0 <= nc < len(result[0]):
                        result[nr][nc] = 5
            else:
                # Different directions - just horizontal/vertical or diagonal
                if dr == 0:  # Horizontal
                    for nc in range(min(c, pc)+1, max(c, pc)):
                        result[r][nc] = 5
                elif dc == 0:  # Vertical
                    for nr in range(min(r, pr)+1, max(r, pr)):
                        result[nr][c] = 5

    return result

