import json

def run_solution(grid, expected=None):
    """Build output grid based on transformation rules"""
    h, w = len(grid), len(grid[0])

    # Find sources
    sources = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]

    if not sources:
        return [[0]*w for _ in range(h)]

    # Start with zeros
    result = [[0]*w for _ in range(h)]

    # Rule for each value:
    # 1: (-1, +2) diagonal up-right
    # 2: (0, -4) horizontal left 4 cells
    # 3: (+3, 0) vertical down 3 cells (need to verify with D2,D3)
    # 6: (-6, 0) vertical up 6 cells

    # Paths get filled with 5s
    # Cross positions (r1,c2), (r2,c1) get 5s

    # Special "4" appears in some cases (need to understand when)

    for r, c, val in sources:
        # Keep source
        result[r][c] = val

        dr, dc = 0, 0
        if val == 1:
            dr, dc = -1, 2
            # Path: linear interp
            for i in range(1,3):
                nr, nc = r + int(dr * i / 2), c + int(dc * i / 2)  # steps: max(abs(-1),abs(2)) = 2
                if 0 <= nr < h and 0 <= nc < w:
                    result[nr][nc] = 5
        elif val == 2:
            dr, dc = 0, -4
            for nc in range(c-1, c-4):
                if 0 <= nc < w:
                    result[r][nc] = 5
        elif val == 3:
            dr, dc = 3, 0  # Vertical down based on D3
            for _ in range(3):
                nr, nc = r + 1, c
                if 0 <= nr < h:
                    result[nr][nc] = 5
        elif val == 6:
            dr, dc = -6, 0
            for _ in range(6):
                nr, nc = r - 1, c
                if 0 <= nr < h:
                    result[nr][nc] = 5

        # Add projection
        result[r+dr][c+dc] = val

    # Cross positions
    for i in range(len(sources)-1):
        r1, c1, v1 = sources[i]
        for j in range(i+1, len(sources)):
            r2, c2, v2 = sources[j]
            if result[r1][c2] == 0:
                result[r1][c2] = 5
            if result[r2][c1] == 0:
                result[r2][c1] = 5

    return result

