def run_solution_v2(grid):
    """
    Refined rules:
    1. Each source projects to new position with specific dr, dc per value
    2. Project path gets filled with 5s (excluding endpoints)
    3. Cross positions (r1,c2) and (r2,c1) for each source pair become 4
    4. From each 4-position, a diagonal / (-1) goes to edge
    """
    h, w = len(grid), len(grid[0])
    sources = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]

    if not sources:
        return [[0]*w for _ in range(h)]

    result = [[0]*w for _ in range(h)]

    for r, c, val in sources:
        dr, dc = 0, 0
        if val == 1:
            dr, dc, steps = -1, 2, 2
        elif val == 2:
            dr, dc, steps = 0, -4, 4
        elif val == 3:
            dr, dc, steps = 3, 0, 3
        elif val == 6:
            dr, dc, steps = -6, 0, 6

        # Fill path with 5s (exclude endpoints)
        for i in range(1, steps):
            nr = r + dr * i // steps
            nc = c + dc * i // steps
            if 0 <= nr < h and 0 <= nc < w:
                result[nr][nc] = 5

        # Set projection
        result[r+dr][c+dc] = val

    # Cross positions become 4
    for i in range(len(sources)-1):
        r1, c1, v1 = sources[i]
        for j in range(i+1, len(sources)):
            r2, c2, v2 = sources[j]
            cross_pos = (r1, c2)
            if 0 <= cross_pos[0] < h and 0 <= cross_pos[1] < w:
                if result[cross_pos[0]][cross_pos[1]] == 0:
                    result[cross_pos[0]][cross_pos[1]] = 4

    # From each 4, draw / diagonal to edge
    for r in range(h):
        for c in range(w):
            if result[r][c] == 4:
                nr, nc = r + 1, c - 1
                while 0 <= nr < h and 0 <= nc < w:
                    result[nr][nc] = 4
                    nr, nc = nr + 1, nc - 1

    return result

