    result = [[0]*w for _ in range(h)]

    # Step 1: Set sources
    for r, c, val in sources:
        result[r][c] = val

    # Define projection rules: (dr, dc, num_steps)
    def get_proj_steps(val):
        if val == 1:
            return -1, 2, 2  # diag up-right
        elif val == 2:
            return 0, -4, 4  # horiz left
        elif val == 3:
            return 3, 0, 3   # vert down
        elif val == 6:
            return -6, 0, 6  # vert up
        return 0, 0, 1

    # Step 2: Draw cross diagonals
    for i in range(len(sources)):
        r1, c1, v1 = sources[i]
        for j in range(i+1, len(sources)):
            r2, c2, v2 = sources[j]
            cross_pos = (r2, c1)
            if 0 <= cross_pos[0] < h and 0 <= cross_pos[1] < w:
                if result[cross_pos[0]][cross_pos[1]] == 0:
                    result[cross_pos[0]][cross_pos[1]] = 4
                    nr, nc = cross_pos[0] + 1, cross_pos[1] - 1
                    while 0 <= nr < h and 0 <= nc < w:
                        result[nr][nc] = 4
                        nr, nc = nr + 1, nc - 1

    # Step 3: Fill path 5s
    for r, c, val in sources:
        dr, dc, steps = get_proj_steps(val)

        # Calculate intermediate cells along the path
        for i in range(1, steps):
            # Use round to find nearest integer position
            nr = r + round(dr * i / steps)
            nc = c + round(dc * i / steps)
            if 0 <= nr < h and 0 <= nc < w and result[nr][nc] == 0:
                result[nr][nc] = 5

    # Step 4: Set projections if not already set
    for r, c, val in sources:
        dr, dc, steps = get_proj_steps(val)
        pr, pc = r + dr, c + dc
        if 0 <= pr < h and 0 <= pc < w:
            if result[pr][pc] == 0:
                result[pr][pc] = val

    return result

