import json

def run_solution_v7(grid):
    """
    Final clean version:
    - Source positions preserved
    - Cross diagonals for value 3+ only (at below-cross r2,c1)
    - Path fills from source toward projection on MAJOR dimension (row const for horiz, col const for vert)
    - Projection at destination
    """
    h, w = len(grid), len(grid[0])
    sources = sorted([(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0])

    result = [[0]*w for _ in range(h)]

    # Step 1: Set sources
    for r, c, val in sources:
        result[r][c] = val

    # Step 2: Draw cross diagonals (for value 3+) at below-cross (r2,c1)
    for i in range(len(sources)):
        r1, c1, v1 = sources[i]
        for j in range(i+1, len(sources)):
            r2, c2, v2 = sources[j]
            if max(v1, v2) >= 3:
                cross_pos = (r2, c1)
                if 0 <= cross_pos[0] < h and 0 <= cross_pos[1] < w:
                    if result[cross_pos[0]][cross_pos[1]] == 0:
                        result[cross_pos[0]][cross_pos[1]] = 4
                        nr, nc = cross_pos[0] + 1, cross_pos[1] - 1
                        while 0 <= nr < h and 0 <= nc < w:
                            result[nr][nc] = 4
                            nr, nc = nr + 1, nc - 1

    # Step 3: Fill paths - on major dimension only
    for r, c, val in sources:
        dr, dc = 0, 0
        if val == 1:
            dr, dc = -1, 2  # Major: dc=2 (horiz), MINOR: dr=-1
        elif val == 2:
            dr, dc = 0, -4  # Major: dc=-4 (horiz)
        elif val == 3:
            dr, dc = 3, 0   # Major: dr=3 (vert)
        elif val == 6:
            dr, dc = -6, 0  # Major: dr=-6 (vert)

        pr = r + dr
        pc = c + dc

        # Determine if major is horizontal (row const) or vertical (col const)
        if abs(dc) > abs(dr):
            # Fill horizontal: same row, cols between c and pc
            col_min = min(c, pc)
            col_max = max(c, pc)
            for nc in range(col_min, col_max):
                if result[r][nc] == 0:
                    result[r][nc] = 5
        else:
            # Fill vertical: same col, rows between r and pr
            row_min = min(r, pr)
            row_max = max(r, pr)
            for nr in range(row_min, row_max):
                if result[nr][c] == 0:
                    result[nr][c] = 5

    # Step 4: Set projections (not already set)
    for r, c, val in sources:
        dr, dc = 0, 0
        if val == 1:
            dr, dc = -1, 2
        elif val == 2:
            dr, dc = 0, -4
        elif val == 3:
            dr, dc = 3, 0
        elif val == 6:
            dr, dc = -6, 0

        pr, pc = r + dr, c + dc
        if 0 <= pr < h and 0 <= pc < w:
            if result[pr][pc] == 0:
                result[pr][pc] = val

    return result

